# Auto-installer for missing Python packages
def auto_ensure_packages():
    packages = {
        "PIL": "Pillow",
        "selenium": "selenium",
        "webdriver_manager": "webdriver-manager",
        "flask": "Flask",
        "flask_cors": "flask-cors",
        "colorama": "colorama",
        "requests": "requests"
    }
    for import_name, pip_name in packages.items():
        try:
            __import__(import_name)
        except ImportError:
            import shutil
            has_pip = shutil.which("pip") or shutil.which("pip3")
            if not has_pip:
                continue
            print(f"[Auto-Installer] Missing package '{pip_name}'. Attempting automatic installation...")
            success = False
            commands = [
                [sys.executable, "-m", "pip", "install", pip_name],
                ["pip", "install", pip_name],
                ["pip3", "install", pip_name]
            ]
            for cmd in commands:
                try:
                    subprocess.check_call(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    print(f"[Auto-Installer] Successfully installed '{pip_name}' via: {' '.join(cmd)}")
                    success = True
                    break
                except Exception:
                    continue
            if not success:
                print(f"[Auto-Installer] WARNING: Could not auto-install '{pip_name}'. Please install it manually.")

auto_ensure_packages()

