# [PATCH v35.3] EMBEDDED AUTO-CLEANUP THREAD
# (sebelumnya di auto_cleanup.py — sekarang jadi background thread)
# ============================================================
def _embedded_cleanup_worker():
    """Background thread yang bersihkan disk tiap 1 jam (embedded, tidak butuh file lain)."""
    import time as _t, os as _os
    _MAX_AUDIT_ENTRIES = 5000
    _AUDIT_FILES = [
        "/home/container/TITAN_WIN_AUDIT.json",
        "/home/container/TITAN_LOSS_AUDIT.json",
    ]
    _tmp_chrome = "/tmp/titan_chrome_profile"
    _proof_dir = "/home/container/static/proofs"
    _backup_dir = "/home/container/backups"
    _LOG_FILES = ["/home/container/security.log", "/home/container/cf.log"]
    _MAX_LOG_MB = 5
    
    _t.sleep(180)  # Tunggu 3 menit sebelum cek pertama
    while True:
        try:
            # 1. Trim audit JSONL
            for fp in _AUDIT_FILES:
                if not _os.path.exists(fp): continue
                try:
                    with open(fp, "r", encoding="utf-8", errors="ignore") as f:
                        lines = f.readlines()
                    if len(lines) > _MAX_AUDIT_ENTRIES:
                        with open(fp, "w", encoding="utf-8") as f:
                            f.writelines(lines[-_MAX_AUDIT_ENTRIES:])
                        print(f"[CLEANUP] Trimmed {_os.path.basename(fp)}: {len(lines)} -> {_MAX_AUDIT_ENTRIES}")
                except: pass
            
            # 2. Rotate log files > 5 MB
            for fp in _LOG_FILES:
                if not _os.path.exists(fp): continue
                try:
                    if _os.path.getsize(fp) / (1024*1024) > _MAX_LOG_MB:
                        with open(fp, "r", encoding="utf-8", errors="ignore") as f:
                            content = f.read()
                        with open(fp, "w", encoding="utf-8") as f:
                            f.write(f"[LOG ROTATED {time.strftime('%Y-%m-%d %H:%M:%S')}]\n")
                            f.write(content[-500*1024:])
                        print(f"[CLEANUP] Rotated {_os.path.basename(fp)}")
                except: pass
            
            # 3. Cleanup chrome /tmp
            if _os.path.exists(_tmp_chrome):
                for sub in ["Default/Cache", "Default/Code Cache", "Default/GPUCache",
                            "Default/Service Worker", "ShaderCache", "GrShaderCache"]:
                    target = _os.path.join(_tmp_chrome, sub)
                    if _os.path.exists(target):
                        try:
                            _shutil_patch.rmtree(target, ignore_errors=True)
                            _os.makedirs(target, exist_ok=True)
                        except: pass
            
            # 4. Cleanup old proofs > 30 hari
            if _os.path.exists(_proof_dir):
                _now = time.time()
                for fn in _os.listdir(_proof_dir):
                    fp = _os.path.join(_proof_dir, fn)
                    if _os.path.isfile(fp) and (_now - _os.path.getmtime(fp)) > 30*86400:
                        try: _os.remove(fp)
                        except: pass
            
            # 5. Cleanup old backups > 7 hari
            if _os.path.exists(_backup_dir):
                _now = time.time()
                for fn in _os.listdir(_backup_dir):
                    fp = _os.path.join(_backup_dir, fn)
                    if _os.path.isfile(fp) and (_now - _os.path.getmtime(fp)) > 7*86400:
                        try: _os.remove(fp)
                        except: pass
                # [PATCH F5] Cleanup snapshot dirs > 24 jam (keep recent ones)
                _snap_dirs = [_os.path.join(_backup_dir, d) for d in _os.listdir(_backup_dir) if d.startswith("snap_")]
                for _sd in _snap_dirs:
                    if _os.path.isdir(_sd) and (_now - _os.path.getmtime(_sd)) > 24*3600:
                        try: _shutil_patch.rmtree(_sd, ignore_errors=True)
                        except: pass
        except Exception as _e:
            print(f"[CLEANUP] Loop error: {_e}")
        _t.sleep(3600)  # Tiap 1 jam

# Jalankan sekali saat app.py di-load
try:
    threading.Thread(target=_embedded_cleanup_worker, daemon=True).start()
    print("[SYSTEM] Embedded auto-cleanup thread started ✅")
except Exception as _e:
    print(f"[SYSTEM] Cleanup thread error: {_e}")

