# [PATCH F1] AUTO-BACKUP THREAD — Backup data penting tiap 5 menit
# ============================================================
def _embedded_backup_worker():
    """Backup file penting ke /home/container/backups/ tiap 5 menit."""
    import time as _t_bak, os as _os_bak, shutil as _sh_bak, json as _j_bak
    from datetime import datetime as _dt_bak
    
    BACKUP_DIR = "/home/container/backups"
    BACKUP_FILES = [
        "brain_memory.json",
        "licenses.json",
        "central_licenses.json",
        "central_registrations.json",
        "titan_config.json",
        "secrets.json",
        ".titan_hwid",
        "owner_settings.json",
        "uid_violations.json",
    ]
    MAX_BACKUPS = 30  # keep 30 terbaru (2.5 jam history)
    
    _t_bak.sleep(60)  # tunggu 1 menit sebelum backup pertama
    while True:
        try:
            _os_bak.makedirs(BACKUP_DIR, exist_ok=True)
            _ts = _dt_bak.now().strftime("%Y%m%d_%H%M%S")
            _snap_dir = _os_bak.path.join(BACKUP_DIR, f"snap_{_ts}")
            _os_bak.makedirs(_snap_dir, exist_ok=True)
            
            _copied = 0
            for _fn in BACKUP_FILES:
                _src = _os_bak.path.join("/home/container", _fn)
                if _os_bak.path.exists(_src):
                    try:
                        _sh_bak.copy2(_src, _os_bak.path.join(_snap_dir, _fn))
                        _copied += 1
                    except: pass
            
            # Hapus backup lama
            _snaps = sorted([d for d in _os_bak.listdir(BACKUP_DIR) if d.startswith("snap_")])
            if len(_snaps) > MAX_BACKUPS:
                for _old in _snaps[:-MAX_BACKUPS]:
                    try:
                        _sh_bak.rmtree(_os_bak.path.join(BACKUP_DIR, _old))
                    except: pass
            
            print(f"[F1-BACKUP] Snapshot {_ts} — {_copied} files backed up")
        except Exception as _bk_e:
            print(f"[F1-BACKUP] Error: {_bk_e}")
        _t_bak.sleep(300)  # tiap 5 menit

try:
    threading.Thread(target=_embedded_backup_worker, daemon=True).start()
    print("[SYSTEM] Embedded auto-backup thread started ✅")
except Exception as _e:
    print(f"[SYSTEM] Backup thread error: {_e}")

