    def _find_wingo_canvas(self):
        """Cari canvas utama 55five di dalam iframe."""
        if not self.driver:
            return None
        from selenium.webdriver.common.by import By
        # Cari iframe utama
        try:
            self.driver.switch_to.default_content()
            iframes = self.driver.find_elements(By.TAG_NAME, "iframe")
            for iframe in iframes:
                try:
                    self.driver.switch_to.frame(iframe)
                    canvases = self.driver.find_elements(By.TAG_NAME, "canvas")
                    if canvases:
                        # Ambil canvas terbesar
                        canvases.sort(key=lambda c: c.size.get('width', 0) * c.size.get('height', 0), reverse=True)
                        return canvases[0]
                except: pass
                finally:
                    try: self.driver.switch_to.parent_frame()
                    except: pass
        except: pass
        # Fallback: cari di document utama
        try:
            self.driver.switch_to.default_content()
            canvases = self.driver.find_elements(By.TAG_NAME, "canvas")
            if canvases:
                canvases.sort(key=lambda c: c.size.get('width', 0) * c.size.get('height', 0), reverse=True)
                return canvases[0]
        except: pass
        return None
    
    def _get_wingo_button_coords(self, canvas_size, button_type):
        """
        Hitung koordinat tombol berdasarkan tipe.
        Layout Wingo 55five (relative ke canvas width & height):
          - BESAR  : x=0.30w, y=0.855h
          - KECIL  : x=0.70w, y=0.855h
          - HIJAU  : x=0.30w, y=0.905h
          - UNGU   : x=0.50w, y=0.905h
          - MERAH  : x=0.70w, y=0.905h
          - Number : grid 2 baris x 5 kolom, y=0.965h & 0.99h (approx)
        """
        w = canvas_size.get('width', 0)
        h = canvas_size.get('height', 0)
        
        # Detection: apakah layout mobile (w/h < 0.7) atau desktop
        if h > 0 and (w / h) > 0.7:
            # Wider layout — biasanya embedded iframe dengan scaling
            effective_w = w * 0.5625 if h > 0 else w
        
        coords = {
            "Besar":    (int(w * 0.30), int(h * 0.855)),
            "Kecil":    (int(w * 0.70), int(h * 0.855)),
            "Hijau":    (int(w * 0.30), int(h * 0.905)),
            "Ungu":     (int(w * 0.50), int(h * 0.905)),
            "Merah":    (int(w * 0.70), int(h * 0.905)),
            "0":        (int(w * 0.10), int(h * 0.965)),
            "1":        (int(w * 0.30), int(h * 0.965)),
            "2":        (int(w * 0.50), int(h * 0.965)),
            "3":        (int(w * 0.70), int(h * 0.965)),
            "4":        (int(w * 0.90), int(h * 0.965)),
            "5":        (int(w * 0.10), int(h * 0.995)),
            "6":        (int(w * 0.30), int(h * 0.995)),
            "7":        (int(w * 0.50), int(h * 0.995)),
            "8":        (int(w * 0.70), int(h * 0.995)),
            "9":        (int(w * 0.90), int(h * 0.995)),
        }
        return coords.get(button_type, (int(w * 0.5), int(h * 0.855)))
    
    def wingo_auto_bet(self, choice, amount=1000):
        """
        [PATCH B1] Auto-bet Wingo di canvas 55five.
        choice: "Besar" | "Kecil" | "Hijau" | "Ungu" | "Merah" | "0"-"9"
        amount: nominal bet (400-40000)
        Returns: (success, message)
        """
        if not self.driver:
            return False, "Driver tidak aktif"
        try:
            import random as _rnd_wab
            from selenium.webdriver.common.action_chains import ActionChains as _AC_wab
            
            with self.lock:
                canvas = self._find_wingo_canvas()
                if not canvas:
                    return False, "Canvas Wingo tidak ditemukan. Pastikan bot di halaman WinGo."
                
                size = canvas.size
                if size.get('width', 0) < 50 or size.get('height', 0) < 50:
                    return False, f"Canvas terlalu kecil ({size}). Halaman belum load sempurna."
                
                # Cek timer — jangan bet kalau < 5 detik
                try:
                    _sec_left = self.get_seconds_left()
                    if 0 < _sec_left < 5:
                        return False, f"Waktu tidak cukup ({_sec_left}s). Skip bet periode ini."
                except: pass
                
                # Hitung koordinat tombol
                target_x, target_y = self._get_wingo_button_coords(size, choice)
                
                # Humanize jitter ±6px
                jitter_x = _rnd_wab.randint(-6, 6)
                jitter_y = _rnd_wab.randint(-3, 3)
                click_x = target_x + jitter_x
                click_y = target_y + jitter_y
                
                # ActionChains click (relative ke center canvas)
                actions = _AC_wab(self.driver)
                offset_x = click_x - (size['width'] / 2)
                offset_y = click_y - (size['height'] / 2)
                actions.move_to_element_with_offset(canvas, offset_x, offset_y).click().perform()
                self._add_log(f"🎯 [B1-AUTOBET] Click '{choice}' @ ({click_x},{click_y}) dari canvas {size['width']}x{size['height']}")
                
                # Tunggu popup chip selector muncul
                import time as _t_wab
                _t_wab.sleep(1.2)
                
                # Pilih chip amount — cari chip yang match amount
                # Chip biasanya di tengah bawah popup
                # Kita coba klik chip yang paling dekat dengan amount
                chip_coords = {
                    400:    (int(size['width'] * 0.20), int(size['height'] * 0.72)),
                    1000:   (int(size['width'] * 0.30), int(size['height'] * 0.72)),
                    2000:   (int(size['width'] * 0.40), int(size['height'] * 0.72)),
                    5000:   (int(size['width'] * 0.50), int(size['height'] * 0.72)),
                    10000:  (int(size['width'] * 0.60), int(size['height'] * 0.72)),
                    20000:  (int(size['width'] * 0.70), int(size['height'] * 0.72)),
                    50000:  (int(size['width'] * 0.80), int(size['height'] * 0.72)),
                }
                # Cari chip terdekat
                _closest = min(chip_coords.keys(), key=lambda k: abs(k - amount))
                chip_x, chip_y = chip_coords[_closest]
                chip_jx = _rnd_wab.randint(-4, 4)
                chip_jy = _rnd_wab.randint(-2, 2)
                
                _ac2 = _AC_wab(self.driver)
                _ac2.move_to_element_with_offset(canvas, 
                    (chip_x + chip_jx) - size['width']/2, 
                    (chip_y + chip_jy) - size['height']/2).click().perform()
                self._add_log(f"💰 [B1-AUTOBET] Pilih chip ~Rp {_closest:,} @ ({chip_x},{chip_y})")
                
                _t_wab.sleep(1.0)
                
                # Klik tombol confirm (biasanya di tengah-bottom popup)
                confirm_x = int(size['width'] * 0.50)
                confirm_y = int(size['height'] * 0.85)
                confirm_jx = _rnd_wab.randint(-4, 4)
                _ac3 = _AC_wab(self.driver)
                _ac3.move_to_element_with_offset(canvas, 
                    (confirm_x + confirm_jx) - size['width']/2, 
                    confirm_y - size['height']/2).click().perform()
                self._add_log(f"✅ [B1-AUTOBET] Konfirmasi bet @ ({confirm_x},{confirm_y})")
                
                _t_wab.sleep(0.5)
                return True, f"Bet {choice} ~Rp {_closest:,} dispatched"
        except Exception as e:
            return False, f"Auto-bet error: {str(e)}"
    
