                is_pg, is_pragmatic, is_jili, _ = self.detect_slot_provider()
                
                if is_pg:
                    target_y_ratio = 0.915
                elif is_pragmatic:
                    target_y_ratio = 0.88
                elif is_jili:
                    target_y_ratio = 0.89
                else:
                    target_y_ratio = 0.90 # Best generic/universal fallback height ratio inside the canvas
                
                target_y = h * target_y_ratio
                
                # \U0001f6e1\ufe0f ANTI-BOT BYPASS: Random micro-jitter mimics real human finger touches inside the spin button boundary (not raw static bots!)
                jitter_x = random.randint(-14, 14)
                jitter_y = random.randint(-4, 4)
                
                # Calculate coordinates for JS (relative to top left of canvas element)
                click_x = (w / 2) + jitter_x
