                self._dispatch_universal_click(target_el, click_x, click_y, offset_x_ac, offset_y_ac)
                
                self._add_log(f"AI AUTO SPIN: Humanized click coordinate ({click_x}, {click_y}) dispatched to Spin icon on {target_el.tag_name} ({w}x{h}).")
