@app.route('/api/deep_scan', methods=['POST'])
def trigger_deep_scan():
    if engine.state.get("is_scanning"):
        return jsonify({"status": "error", "msg": "Deep Scan already in progress..."}), 400
    threading.Thread(target=engine._perform_deep_scan, args=(10,), daemon=True).start()
    return jsonify({"status": "ok"})

# [PATCH A3.1] Soft Reset Sync — TIDAK restart Chrome, hanya reset state AI
@app.route('/api/reset_sync', methods=['POST'])
def reset_sync_soft():
    """[HARD SYNC v2] Reset total + navigate paksa + klik tab + deep scan."""
    try:
        data = request.get_json(silent=True) or {}
        _target_mode = str(data.get("mode", "1m")).strip().lower()
        _mode_id_map = {"30s": "0", "1m": "1", "3m": "3", "5m": "5"}
        _mode_sec_map = {"30s": "30", "1m": "60", "3m": "180", "5m": "300"}
        _mode_label_map = {"30s": "MODE: 30 SEC", "1m": "MODE: 1 MIN", "3m": "MODE: 3 MIN", "5m": "MODE: 5 MIN"}
        
        engine._add_log(f"🔄 [HARD SYNC v2] Reset total ke mode '{_target_mode}'...")
        
        # 1. Interrupt deep scan yang sedang jalan
        try:
            engine.interrupt_scan = True
            for _w in range(20):
                if not engine.state.get("is_scanning"): break
                time.sleep(0.1)
            engine.state["is_scanning"] = False
        except: pass
        
        # 2a. [LOCK] Blokir monitor loop 8 detik (cukup untuk navigate + klik tab)
        engine.hard_sync_until = time.time() + 8
        
        # 2b. [ANTI-DRIFT] Set active_sig sesuai kode mode target
        try:
            _date_str_hs = datetime.now().strftime("%Y%m%d")
            _code_map_hs = {"30s": "10005", "1m": "10001", "3m": "10002", "5m": "10003"}
            engine.state["active_sig"] = f"{_date_str_hs}{_code_map_hs.get(_target_mode, '10001')}"
        except: pass
        
        # 2c. FULL state reset (SEMUA variabel, tidak ada yang tertinggal)
        engine.processed_p = set()
        engine.drift_counter = 0
        engine.state["history"] = []
        engine.state["prediction"] = None
        # [PATCH] JANGAN override active_sig — sudah di-set di step 2b untuk mode target
        # engine.state["active_sig"] = None
        engine.state["active_p"] = None
        engine.state["active_period"] = None
        engine.state["currentPeriod"] = None
        engine.state["target_period"] = None
        engine.state["mode_raw"] = _mode_sec_map.get(_target_mode, "60")
        engine.state["current_mode"] = _mode_label_map.get(_target_mode, "MODE: 1 MIN")
        engine.last_sync_time = time.time()
        engine.last_observed_timer = ""
        engine.last_timer_change_time = time.time()
        
        # 3. Reset brain memory
        try:
            engine.brain.processed_p = set()
            engine.brain.sequence_map.clear()
            engine.brain.history_nums = []
            engine.brain.history_bks = []
            engine.brain.history_colors = []
            engine.brain.intensity = {"Besar": 0, "Kecil": 0}
            engine.brain.chart_stats = {
                "missing": [0]*10, "avg_missing": [0]*10,
                "frequency": [0]*10, "max_streak": [0]*10
            }
        except: pass
        
        # 4. Clear signals & archives
        engine.tg_signals = []
        engine.prediction_archive = {}
        
        # 5. Simpan force_mode ke owner_settings
        try:
            _os_path = "/home/container/owner_settings.json"
            _settings = _load_owner_settings_local()
            _settings["force_mode"] = _target_mode
            with open(_os_path, "w") as _sf:
                json.dump(_settings, _sf, indent=2)
        except: pass
        
        # 6. Navigate paksa ke URL yang benar (dengan safety check)
        _nav_ok = False
        _tab_clicked = False
        # Cek driver masih hidup sebelum dipakai
        _driver_alive = False
        if engine.driver:
            try:
                _ = engine.driver.current_url
                _driver_alive = True
            except Exception:
                _driver_alive = False
                engine._add_log("⚠️ [HARD SYNC] Driver mati, skip navigate. Monitor akan recovery otomatis.")
        if _driver_alive:
            try:
                with engine.lock:
                    _base_url = "https://www.nuxpira.com"
                    _cur = engine.driver.current_url or ""
                    if "/#/" in _cur:
                        _base_url = _cur.split("/#/")[0]
                    _target_url = f"{_base_url}/#/home/AllLotteryGames/WinGo?id={_mode_id_map.get(_target_mode, '1')}"
                    engine._add_log(f"🌐 [HARD SYNC] Navigate: {_target_url}")
                    engine.driver.get(_target_url)
                    _nav_ok = True
            except Exception as _nav_e:
                engine._add_log(f"⚠️ [HARD SYNC] Navigate error: {_nav_e}")
        
        # 7. Tunggu page render singkat + klik tab (FAST MODE)
        if _nav_ok and engine.driver:
            time.sleep(1.2)
            try:
                with engine.lock:
                    _targets = {
                        "30s": ["30s", "30 s", "30sec", "30 sec", "30 detik"],
                        "1m": ["1m", "1 min", "1min", "1 menit", "1menit"],
                        "3m": ["3m", "3 min", "3min", "3 menit", "3menit"],
                        "5m": ["5m", "5 min", "5min", "5 menit", "5menit"]
                    }.get(_target_mode, ["1m"])
                    
                    # Klik paksa dengan JS, hapus overlay, dan verifikasi tab aktif
                    _tab_clicked = engine.driver.execute_script("""
                        (function(){
                            var targets = arguments[0];
                            
                            // LANGKAH 1: Hapus semua overlay/popup yang menghalangi
                            var overlays = document.querySelectorAll('.van-overlay, [class*="overlay"], .van-popup, [class*="popup"], [class*="modal"], .van-dialog');
                            for (var o = 0; o < overlays.length; o++) {
                                try { overlays[o].remove(); } catch(e){}
                            }
                            
                            // LANGKAH 2: Cari dan klik tab target dengan multiple fallback
                            var allTabs = document.querySelectorAll('.van-tab, [role="tab"], [class*="tab-item"], [class*="tab"], button, span, div');
                            var clicked = false;
                            var targetElement = null;
                            
                            for (var k = 0; k < allTabs.length; k++) {
                                var el = allTabs[k];
                                var txt = (el.innerText || '').toLowerCase().trim();
                                if (txt.length > 25 || txt.length === 0) continue;
                                
                                for (var m = 0; m < targets.length; m++) {
                                    if (txt === targets[m] || (txt.indexOf(targets[m]) > -1 && txt.length < 12)) {
                                        targetElement = el;
                                        // Coba klik via JS click()
                                        try { el.click(); clicked = true; } catch(e){}
                                        // Fallback: dispatch event manual
                                        if (!clicked) {
                                            try {
                                                var evt = new MouseEvent('click', {bubbles: true, cancelable: true, view: window});
                                                el.dispatchEvent(evt);
                                                clicked = true;
                                            } catch(e){}
                                        }
                                        break;
                                    }
                                }
                                if (clicked) break;
                            }
                            
                            // LANGKAH 3: Verifikasi apakah tab target sudah aktif
                            var verified = false;
                            var checkTabs = document.querySelectorAll('.van-tab--active, .van-tab.active, [class*="active"][class*="tab"]');
                            for (var v = 0; v < checkTabs.length; v++) {
                                var vt = (checkTabs[v].innerText || '').toLowerCase();
                                for (var n = 0; n < targets.length; n++) {
                                    if (vt.indexOf(targets[n]) > -1) {
                                        verified = true;
                                        break;
                                    }
                                }
                                if (verified) break;
                            }
                            
                            return {clicked: clicked, verified: verified, targetFound: targetElement !== null};
                        })(arguments[0]);
                    """, _targets)
                    
                    _tab_clicked = _tab_clicked and _tab_clicked.get("verified", False)
                    
                    # LANGKAH 4: Verifikasi ulang setelah jeda (retry jika belum aktif)
                    if not _tab_clicked:
                        time.sleep(1.5)
                        _tab_clicked = engine.driver.execute_script("""
                            (function(){
                                var targets = arguments[0];
                                // Cari elemen tab target dan klik paksa lagi
                                var allEls = document.querySelectorAll('*');
                                for (var k = 0; k < allEls.length; k++) {
                                    var el = allEls[k];
                                    var txt = (el.innerText || '').toLowerCase().trim();
                                    if (txt.length > 20 || txt.length === 0) continue;
                                    for (var m = 0; m < targets.length; m++) {
                                        if (txt.indexOf(targets[m]) > -1 && txt.length < 12) {
                                            try {
                                                el.click();
                                                var evt = new MouseEvent('click', {bubbles: true});
                                                el.dispatchEvent(evt);
                                            } catch(e){}
                                            return true;
                                        }
                                    }
                                }
                                return false;
                            })(arguments[0]);
                        """, _targets)
            except Exception as _click_err:
                engine._add_log(f"⚠️ [HARD SYNC] Tab click error: {_click_err}")
        
        # 8. Trigger Deep Scan untuk tarik periode baru secara instan
        try:
            import threading as _th_hs
            _th_hs.Thread(target=engine._perform_deep_scan, args=(3,), daemon=True).start()
            engine._add_log("🔍 [HARD SYNC] Deep Scan 3 halaman untuk sync periode baru...")
        except: pass
        
        engine._add_log(f"✅ [HARD SYNC] Selesai. Mode={_target_mode}, Tab={_tab_clicked}, Nav={_nav_ok}")
        
        # 9. [FORCE PREDICT] Hanya jika driver masih hidup
        try:
            _driver_ok_fp = False
            if engine.driver:
                try:
                    _ = engine.driver.current_url
                    _driver_ok_fp = True
                except: pass
            if _driver_ok_fp:
                _sec_target = _mode_sec_map.get(_target_mode, "60")
                _official_p = engine.get_official_utc_period(_sec_target)
                if _official_p:
                    engine._add_log(f"🎯 [HARD SYNC] Force predict periode: {_official_p}")
                    engine._do_predict(explicit_target=_official_p, force=True)
            else:
                engine._add_log("⚠️ [HARD SYNC] Skip force predict (driver mati). Deep scan akan handle saat recovery.")
        except Exception as _fp_err:
            engine._add_log(f"⚠️ [HARD SYNC] Force predict error: {_fp_err}")
        
        # 10. [LIVE POLER] Poll DOM 8 detik untuk catch periode baru mode ini
        try:
            import threading as _th_poll
            def _live_poll_worker():
                _seen_periods = set()
                _deadline = time.time() + 8.0
                _expected_code = _code_map_hs.get(_target_mode, "10001")
                while time.time() < _deadline:
                    try:
                        if not engine.driver: break
                        with engine.lock:
                            _poll_txt = engine.driver.execute_script(
                                "var el=document.querySelector('.TimeLeft__C, [class*='TimeLeft'], .game-info, .game-head'); "
                                "return el ? (el.innerText||'') : (document.body ? document.body.innerText : '');"
                            ) or ""
                        import re as _re_poll
                        for _m in _re_poll.finditer(r'(202\d{14})', _poll_txt.replace(' ', '').replace('\n', '')):
                            _p_clean = _m.group(1)
                            if _p_clean[8:13] != _expected_code: continue
                            if _p_clean in _seen_periods: continue
                            _seen_periods.add(_p_clean)
                            # Cari digit hasil di sekitar
                            _idx = _poll_txt.find(_p_clean)
                            if _idx >= 0:
                                _snippet = _poll_txt[_idx+17:_idx+80]
                                _dm = _re_poll.search(r'\b([0-9])\b', _snippet)
                                if _dm:
                                    engine._on_result(_p_clean, int(_dm.group(1)))
                    except: pass
                    time.sleep(0.5)
            _th_poll.Thread(target=_live_poll_worker, daemon=True).start()
            engine._add_log(f"🔍 [HARD SYNC] Live poll aktif 8 detik untuk mode {_target_mode}...")
        except Exception as _poll_err:
            engine._add_log(f"⚠️ [HARD SYNC] Live poll error: {_poll_err}")
        
        return jsonify({
            "status": "ok",
            "msg": f"Hard sync ke mode {_target_mode.upper()} berhasil",
            "mode": _target_mode,
            "tab_clicked": _tab_clicked,
            "navigate_ok": _nav_ok,
            "period_reset": True
        })
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500

