@app.route('/api/admin/backup_export', methods=['GET'])
def api_admin_backup_export():
    """Download backup ZIP berisi file CORE + CONFIG + IDENTITY."""
    try:
        admin_key = request.args.get("key", "")
        OWNER_MASTER_KEY = "MASTER_OWNER_TITAN"
        if admin_key != OWNER_MASTER_KEY:
            return jsonify({"status": "error", "msg": "Unauthorized"}), 403
        
        import zipfile as _zip_h1, io as _io_h1
        from datetime import datetime as _dt_h1
        
        buf = _io_h1.BytesIO()
        ts = _dt_h1.now().strftime("%Y%m%d_%H%M%S")
        
        CORE_FILES = ["app.py", "central_server.py", "otak.py", "otak_slot.py", "titan_web.py", "requirements.txt"]
        CONFIG_FILES = ["secrets.json", "titan_config.json", "owner_settings.json"]
        IDENTITY_FILES = [".titan_hwid"]
        DATA_FILES = ["central_licenses.json", "central_registrations.json", "licenses.json", "brain_memory.json", "member_settings.json"]
        
        with _zip_h1.ZipFile(buf, "w", _zip_h1.ZIP_DEFLATED) as zf:
            for fname in CORE_FILES:
                p = os.path.join("/home/container", fname)
                if os.path.exists(p):
                    zf.write(p, f"CORE/{fname}")
            for fname in CONFIG_FILES:
                p = os.path.join("/home/container", fname)
                if os.path.exists(p):
                    zf.write(p, f"CONFIG/{fname}")
            for fname in IDENTITY_FILES:
                p = os.path.join("/home/container", fname)
                if os.path.exists(p):
                    zf.write(p, f"IDENTITY/{fname}")
            for fname in DATA_FILES:
                p = os.path.join("/home/container", fname)
                if os.path.exists(p):
                    zf.write(p, f"DATA/{fname}")
            # Tambah MIGRATION_GUIDE
            guide = "TITANIUM OMEGA - MIGRATION GUIDE\n" + "="*50 + "\n\n" + \
                    "1. VPS BARU: Setup Python 3.11 Pterodactyl\n" + \
                    "2. Upload folder CORE/ → /home/container/\n" + \
                    "3. Upload folder CONFIG/ → /home/container/\n" + \
                    "4. Upload folder IDENTITY/ → /home/container/\n" + \
                    "5. (Opsional) Upload DATA/ → /home/container/\n" + \
                    "6. Install Chrome binary + libs via manual_libs.py\n" + \
                    "7. Startup Command: python central_server.py & SERVER_PORT=5000 python app.py\n" + \
                    "8. Restart. Cek console: '[SECURITY] Loaded secrets.json ✅'\n" + \
                    "\nKONTAK SUPPORT: @raniwealth\n" + \
                    "TANGGAL BACKUP: " + ts + "\n"
            zf.writestr("MIGRATION_GUIDE.txt", guide)
        
        buf.seek(0)
        return Response(
            buf.getvalue(),
            mimetype="application/zip",
            headers={"Content-Disposition": f"attachment; filename=titan_backup_{ts}.zip"}
        )
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500


