@app.route('/api/restart', methods=['POST'])
def restart_engine():
    engine._add_log("MANUAL OVERRIDE: Re-initializing Neural Engine...")
    engine.last_sync_time = time.time()
    # [WORKFLOW v2] Set target_url ke LOGIN page
    try:
        engine.target_url = LOGIN_URL
        engine._add_log(f"🎯 [WORKFLOW] Set target_url ke LOGIN page")
    except Exception as _t_e:
        engine._add_log(f"⚠️ Set target error: {_t_e}")
    # Reset state sync saat restart
    try:
        engine.processed_p = set()
        engine.state["history"] = []
        engine.state["prediction"] = None
        engine.state["active_sig"] = None
        engine.state["active_p"] = None
        engine.state["currentPeriod"] = None
        engine.state["mode_raw"] = "60"
        engine.state["current_mode"] = "WAITING FOR LOGIN"
        engine._add_log("🔄 [WORKFLOW] Reset state — silakan login + klik mode untuk Sync.")
    except Exception as _r_e:
        engine._add_log(f"⚠️ Reset error: {_r_e}")
    def _do_reboot():
        try:
            if engine.driver:
                engine.driver.quit()
        except: pass
        engine.driver = None
        engine.is_running = False
        time.sleep(2)
        engine.is_running = True
        threading.Thread(target=engine.start_browser, daemon=True).start()
        threading.Thread(target=engine.monitor_loop, daemon=True).start()
    threading.Thread(target=_do_reboot, daemon=True).start()
    return jsonify({"status": "ok"})

