def require_admin(f):
    from functools import wraps
    @wraps(f)
    def decorated_function(*args, **kwargs):
        is_owner = check_owner_mode()
        if not is_owner:
            return jsonify({"status": "error", "msg": "Unauthorized Admin Access"}), 403
            
        if os.environ.get("TITAN_OWNER_MODE") == "1" or os.environ.get("SPAWNED_BY_NODE") == "1":
            return f(*args, **kwargs)
        key = request.args.get('key') or request.headers.get('X-Admin-Key')
        admin_pass = request.headers.get('X-Admin-Pass')
        if key == _APP_SECRETS.get("OWNER_MASTER_KEY", "MASTER_OWNER_TITAN") or admin_pass == engine.admin_pass:
            return f(*args, **kwargs)
        return jsonify({"status": "error", "msg": "Unauthorized Access Detected"}), 403
    return decorated_function

