# [PHASE 1a SAFE] Tidak lagi simpan kredensial plaintext
# Login hanya 1x manual → Chrome simpan session di profile
_55FIVE_CRED_FILE = "/home/container/.titan_session_marker"  # marker, bukan credential

def _load_55five_creds():
    # [PHASE 1a SAFE] Hanya cek marker, tidak ada kredensial
    return {"enabled": False, "username": "", "password": ""}

def _save_55five_creds(data):
    try:
        with open(_55FIVE_CRED_FILE, "w") as f:
            json.dump(data, f, indent=2)
        try: os.chmod(_55FIVE_CRED_FILE, 0o600)
        except: pass
        return True
    except: return False

def _auto_login_55five():
    """Auto-login ke 55five pakai kredensial tersimpan."""
    if not engine or not engine.driver:
        return False, "Browser tidak aktif"
    c = _load_55five_creds()
    if not c.get("enabled"):
        return False, "Auto-login belum diaktifkan"
    u = str(c.get("username", "")).strip()
    p = str(c.get("password", "")).strip()
    if not u or not p:
        return False, "Kredensial kosong"
    try:
        ok, msg = engine.login_automatic(u, p)
        return ok, msg
    except Exception as e:
        return False, str(e)

@app.route('/api/admin/save_55five_login', methods=['POST'])
def api_save_55five_login():
    """[PHASE 1a] Simpan kredensial auto-login 55five."""
    try:
        data = request.get_json(silent=True) or {}
        admin_key = str(data.get("key", "")).strip()
        OWNER_MASTER_KEY = _APP_SECRETS.get("OWNER_MASTER_KEY", "")
        if admin_key != OWNER_MASTER_KEY:
            return jsonify({"status": "error", "msg": "Unauthorized"}), 403
        
        username = str(data.get("username", "")).strip()
        password = str(data.get("password", "")).strip()
        enabled = bool(data.get("enabled", False))
        
        if enabled and (not username or not password):
            return jsonify({"status": "error", "msg": "Username & Password wajib diisi"}), 400
        
        # Pertahankan password lama kalau field kosong
        old = _load_55five_creds()
        if not password and old.get("password"):
            password = old["password"]
        
        cred_data = {
            "username": username,
            "password": password,
            "enabled": enabled,
            "saved_at": __import__("datetime").datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        }
        if _save_55five_creds(cred_data):
            engine._add_log(f"🔐 [PHASE 1a] Kredensial 55five tersimpan (enabled={enabled})")
            return jsonify({"status": "ok", "msg": "Kredensial tersimpan"})
        return jsonify({"status": "error", "msg": "Gagal simpan file"}), 500
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500

