@app.route('/api/admin/keys', methods=['GET', 'POST', 'DELETE'])
@require_admin
def admin_keys():
    if request.method == 'GET':
        engine._load_licenses()
        return jsonify(engine.licenses)
    elif request.method == 'POST':
        data = request.json or {}
        custom_key = data.get("key", "").strip() or data.get("custom_key", "").strip()
        days = int(data.get("days", 30))
        buyer_name = data.get("name", "").strip() or data.get("buyer_name", "").strip() or "MEMBER"
        account_id = data.get("account_id", "").strip() or None
        custom_hwid = data.get("hwid", "").strip() or None
        
        if "expiry" in data and data.get("expiry", "").strip():
            expiry_date = data.get("expiry", "").strip()
            # Try to parse and get YYYYMMDD
            try:
                dt_p = datetime.strptime(expiry_date, "%Y-%m-%d %H:%M:%S")
                expiry_yyyymmdd = dt_p.strftime("%Y%m%d")
            except:
                expiry_yyyymmdd = "99991231"
        elif days >= 3650:
            expiry_date = "9999-12-31 23:59:59"
            expiry_yyyymmdd = "99991231"
        else:
            expiry_date = (datetime.now() + timedelta(days=days)).strftime("%Y-%m-%d %H:%M:%S")
            expiry_yyyymmdd = (datetime.now() + timedelta(days=days)).strftime("%Y%m%d")

        if custom_key:
            key = custom_key
        else:
            acc_clean = "".join(c for c in (account_id or "ANYID") if c.isalnum()).upper()
            hw_clean = "".join(c for c in (custom_hwid or "ANYHWID") if c.isalnum()).upper()
            sig = engine.generate_offline_sig(expiry_yyyymmdd, acc_clean, hw_clean)
            key = f"TITAN-VIP-{expiry_yyyymmdd}-{acc_clean}-{hw_clean}-{sig}"
            
        engine._load_licenses()
        engine.licenses[key] = {
            "buyer_name": buyer_name,
            "account_id": account_id,
            "hwid": custom_hwid,
            "expiry": expiry_date,
            "active": True
        }
        engine._save_licenses()
        return jsonify({"status": "ok", "key": key})
    elif request.method == 'DELETE':
        key = request.args.get("key")
        engine._load_licenses()
        if key in engine.licenses:
            del engine.licenses[key]
            engine._save_licenses()
        return jsonify({"status": "ok"})
@app.route('/api/central_verify', methods=['POST'])
def central_verify():
    data = request.json or {}
    key = data.get("key", "").strip()
    account_id = data.get("account_id", "").strip()
    my_hwid = data.get("hwid", "").strip()
    
    if not key:
        return jsonify({"status": "error", "msg": "License register mismatch: missing key"}), 400
        
    engine._load_licenses()
    if key not in engine.licenses:
        return jsonify({"status": "error", "msg": "License Key not registered on cloud registry"}), 404
        
    lic = engine.licenses[key]
    
    # 0. Verify Active Status
    is_active = lic.get("active", True)
    if not is_active:
        return jsonify({"status": "error", "msg": "License is DEACTIVATED or SUSPENDED by Admin owner! Please contact @raniwealth."}), 403
        
    # 1. Verify Account ID (if pre-defined by owner)
    saved_acc = lic.get("account_id")
    if saved_acc:
        if str(saved_acc).strip() != str(account_id).strip():
            return jsonify({"status": "error", "msg": "Member ID mismatch on centralized database"}), 403
            
    # 2. Verify or Bind HWID
    saved_hwid = lic.get("hwid")
    if not saved_hwid:
        # Auto-bind member's computer hardware lock dynamically!
        lic["hwid"] = my_hwid
        engine._save_licenses()
        print(f"[CENTRAL] Locked key {key} to HWID {my_hwid}")
    elif saved_hwid != my_hwid:
        return jsonify({"status": "error", "msg": "License hardware locked to another device! Reset via owner panel."}), 403
        
    # 3. Verify Expiry
    expiry_str = str(lic.get("expiry", "2030-01-01 00:00:00")).strip().upper()
    is_lifetime = "LIFETIME" in expiry_str or "SELAMANYA" in expiry_str or "9999" in expiry_str or expiry_str == "3650" or expiry_str == "36500"
    if not is_lifetime:
        try:
            exp = datetime.strptime(lic["expiry"], "%Y-%m-%d %H:%M:%S")
            if datetime.now() > exp:
                return jsonify({"status": "error", "msg": "License signature expired"}), 403
        except Exception as e:
            # Fallback fail-safe for minor admin typos/format changes (avoid breaking the user with a 500 error)
            pass
        
    # Return success details
    return jsonify({
        "status": "ok",
        "msg": "Authorized",
        "license": {
            "buyer_name": lic.get("buyer_name", "MEMBER"),
            "expiry": lic.get("expiry")
        },
        "target_url": engine.target_url or "https://www.nuxpira.com/#/login"
    })

