# ============================================================
# [PATCH O2] MEMBER API — Distribution untuk 1000 Member
# ============================================================

# [PATCH E2] Enhanced Rate Limiter — Handle 1000+ member
_member_rate = {}  # {token: [timestamps]}
_member_rate_last_cleanup = 0
_MEMBER_RATE_LIMIT = 10  # naikkan dari 6 → 10 req/menit per token
_MEMBER_RATE_WINDOW = 60  # detik
_MAX_TOKENS_IN_MEMORY = 5000  # auto cleanup kalau > 5000

def _check_member_rate(token):
    """Rate limiter untuk member API. Max 10 req/menit per token."""
    global _member_rate_last_cleanup
    import time as _t_r
    now = _t_r.time()
    
    # [PATCH E2] Auto cleanup tiap 5 menit untuk cegah memory leak
    if now - _member_rate_last_cleanup > 300:
        _member_rate_last_cleanup = now
        # Hapus token yang sudah lama tidak aktif (>10 menit)
        stale = [k for k, v in _member_rate.items() if not v or now - v[-1] > 600]
        for k in stale:
            del _member_rate[k]
        # Kalau masih > MAX, hapus yang paling lama
        if len(_member_rate) > _MAX_TOKENS_IN_MEMORY:
            sorted_tokens = sorted(_member_rate.items(), key=lambda x: x[1][-1] if x[1] else 0)
            to_remove = len(_member_rate) - _MAX_TOKENS_IN_MEMORY
            for k, _ in sorted_tokens[:to_remove]:
                del _member_rate[k]
    
    if token not in _member_rate:
        _member_rate[token] = []
    _member_rate[token] = [ts for ts in _member_rate[token] if now - ts < _MEMBER_RATE_WINDOW]
    if len(_member_rate[token]) >= _MEMBER_RATE_LIMIT:
        return False
    _member_rate[token].append(now)
    return True

def _find_license_by_token(member_token):
    """[PATCH O2.6 + FIX-APP v2] Baca LANGSUNG dari file, bypass memory cache.
    Tidak akan pernah 'Invalid Token' selama license ada di file."""
    if not member_token:
        return None, None
    
    _clean_token = str(member_token).strip()
    if not _clean_token:
        return None, None
    
    try:
        import json as _j_fix, os as _o_fix
        
        # [BULLETPROOF] Baca LANGSUNG dari file, tidak bergantung memory
        _merged = {}
        _files_checked = []
        for _fp in [
            "/home/container/licenses.json",
            "/home/container/central_licenses.json"
        ]:
            if _o_fix.path.exists(_fp):
                _files_checked.append(_fp)
                try:
                    with open(_fp, "r") as _f:
                        _data = _j_fix.load(_f)
                        if isinstance(_data, dict):
                            _merged.update(_data)
                except Exception as _read_e:
                    print(f"[_find_license] Read error {_fp}: {_read_e}")
        
        print(f"[_find_license] Token: '{_clean_token[:40]}...' | Files: {_files_checked} | Total keys: {len(_merged)}")
        
        # 1. Direct match (paling umum)
        if _clean_token in _merged:
            _lic = _merged[_clean_token]
            print(f"[_find_license] ✓ Direct match found")
            try:
                engine.licenses[_clean_token] = _lic
            except: pass
            return _clean_token, _lic
        
        # 2. Match by member_token field
        for _k, _v in _merged.items():
            if isinstance(_v, dict) and _v.get("member_token") == _clean_token:
                print(f"[_find_license] ✓ Member-token match found")
                try:
                    engine.licenses[_k] = _v
                except: pass
                return _k, _v
        
        # 3. Match by strip compare (handle whitespace)
        for _k, _v in _merged.items():
            if str(_k).strip() == _clean_token:
                print(f"[_find_license] ✓ Stripped match found")
                try:
                    engine.licenses[_k] = _v
                except: pass
                return _k, _v
        
        # 4. Partial match — cari kunci yang cocok 90% (handles typo)
        for _k, _v in _merged.items():
            if str(_k).strip().startswith(_clean_token[:30]):
                print(f"[_find_license] ⚠️ Partial match found: {_k[:30]}...")
                try:
                    engine.licenses[_k] = _v
                except: pass
                return _k, _v
        
        print(f"[_find_license] ✗ NOT FOUND. Sample keys: {list(_merged.keys())[:3]}")
    except Exception as _e:
        print(f"[_find_license] Critical error: {_e}")
    
    return None, None


