# [PATCH G3] MEMBER SETTINGS API — Money Management
# ============================================================
MEMBER_SETTINGS_FILE = "/home/container/member_settings.json"

def _load_member_settings():
    try:
        if os.path.exists(MEMBER_SETTINGS_FILE):
            with open(MEMBER_SETTINGS_FILE, "r") as f:
                return json.load(f)
    except: pass
    return {}

def _save_member_settings(data):
    try:
        with open(MEMBER_SETTINGS_FILE, "w") as f:
            json.dump(data, f, indent=2)
        return True
    except: return False

@app.route('/api/member/settings/save', methods=['POST'])
def member_save_settings_v1():
    """[PATCH G3] Simpan setting member (mode, money mgmt)."""
    try:
        data = request.json or {}
        token = str(data.get("token", "")).strip()[:64]
        if not token:
            return jsonify({"status": "error", "msg": "Token required"}), 400
        if not _check_member_rate(token):
            return jsonify({"status": "error", "msg": "Rate limit"}), 429
        key, lic = _find_license_by_token(token)
        if not lic:
            return jsonify({"status": "error", "msg": "Invalid token"}), 403
        
        all_settings = _load_member_settings()
        current = all_settings.get(key, {})
        
        # Mode
        if "play_mode" in data and data["play_mode"] in ("signal", "copilot", "auto"):
            current["play_mode"] = data["play_mode"]
        
        # Money mgmt
        for fld in ["capital", "target", "stoploss", "bet", "max_level", "multiplier"]:
            if fld in data:
                try:
                    val = int(data[fld])
                    if val > 0: current[fld] = val
                except: pass
        
        current["updated_at"] = __import__("datetime").datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        all_settings[key] = current
        _save_member_settings(all_settings)
        
        return jsonify({"status": "ok", "settings": current})
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500

@app.route('/api/member/settings/get', methods=['GET'])
def member_get_settings_v1():
    """[PATCH G3] Ambil setting member."""
    try:
        token = str(request.args.get("token", "")).strip()[:64]
        if not token:
            return jsonify({"status": "error", "msg": "Token required"}), 400
        if not _check_member_rate(token):
            return jsonify({"status": "error", "msg": "Rate limit"}), 429
        key, lic = _find_license_by_token(token)
        if not lic:
            return jsonify({"status": "error", "msg": "Invalid token"}), 403
        
        all_settings = _load_member_settings()
        current = all_settings.get(key, {})
        # Default values
        defaults = {"play_mode": "signal", "capital": 1000000, "target": 500000,
                    "stoploss": 200000, "bet": 1000, "max_level": 3, "multiplier": 2}
        for k, v in defaults.items():
            current.setdefault(k, v)
        return jsonify({"status": "ok", "settings": current})
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500

