@app.route('/api/member/bet_report', methods=['POST'])
def api_member_bet_report():
    """[PATCH G6.1] Bookmarklet report bet result untuk audit trail."""
    try:
        data = request.json or {}
        token = str(data.get("token", "")).strip()[:64]
        if not token:
            return jsonify({"status": "error", "msg": "Token required"}), 400
        key, lic = _find_license_by_token(token)
        if not lic:
            return jsonify({"status": "error", "msg": "Invalid token"}), 403
        
        # Simpan log
        log_file = "/home/container/member_bet_logs.json"
        logs = []
        if os.path.exists(log_file):
            try:
                with open(log_file, "r") as f:
                    logs = json.load(f)
            except: pass
        
        from datetime import datetime as _dt_br
        entry = {
            "timestamp": _dt_br.now().strftime("%Y-%m-%d %H:%M:%S"),
            "member_uid": lic.get("account_id", "?"),
            "target": str(data.get("target", ""))[:20],
            "side": str(data.get("side", ""))[:10],
            "num": data.get("num", 0),
            "bet": int(data.get("bet", 0)),
            "level": int(data.get("level", 1)),
            "result": str(data.get("result", ""))[:20],
        }
        logs.append(entry)
        # Keep max 10000 entry
        with open(log_file, "w") as f:
            json.dump(logs[-10000:], f, indent=2)
        
        return jsonify({"status": "ok"})
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500


