# [PATCH O2.3] Member terima prediksi terbaru
@app.route('/api/member/prediction', methods=['GET'])
def member_prediction_v1():
    try:
        token = str(request.args.get("token", "")).strip()[:64]
        if not token:
            return jsonify({"status": "error", "msg": "Token required"}), 400
        if not _check_member_rate(token):
            return jsonify({"status": "error", "msg": "Rate limit exceeded"}), 429
        key, lic = _find_license_by_token(token)
        if not lic:
            return jsonify({"status": "error", "msg": "Invalid token"}), 403
        # Cek active
        if not lic.get("active", True):
            return jsonify({"status": "error", "msg": "License suspended"}), 403
        # Cek expiry
        try:
            from datetime import datetime as _dt_exp
            _exp = _dt_exp.strptime(lic["expiry"], "%Y-%m-%d %H:%M:%S")
            if _dt_exp.now() > _exp:
                return jsonify({"status": "error", "msg": "License expired"}), 403
        except: pass
        # Ambil prediksi terbaru dari engine state
        pred = None
        try:
            if engine and hasattr(engine, "state"):
                p = engine.state.get("prediction")
                # [PATCH A2.4] Fallback ke brain internal jika state kosong
                _brain = getattr(engine, "brain", None)
                _brain_phase = getattr(_brain, "market_mood", "STABLE") if _brain else "STABLE"
                _brain_entropy = getattr(_brain, "quantum_entropy", 0.0) if _brain else 0.0
                
                if p and p.get("target") and p.get("bk"):
                    # Prediksi valid — pakai dengan fallback
                    _conf = p.get("acc")
                    if not _conf or _conf in (0, "0"):
                        _conf = p.get("confidence")
                    if not _conf or _conf in (0, "0"):
                        _conf = 75
                    _entropy = p.get("entropy")
                    if _entropy is None or _entropy == "" or _entropy == 0:
                        _entropy = _brain_entropy
                    _phase = p.get("phase") or _brain_phase
                    pred = {
                        "target": p.get("target") or "",
                        "bk": p.get("bk") or "Besar",
                        "num": p.get("num") if p.get("num") is not None else 5,
                        "confidence": _conf,
                        "action": p.get("action", "TITAN-ACTIVE"),
                        "entropy": round(float(_entropy), 3) if _entropy else 0,
                        "phase": _phase,
                        "is_jp": bool(p.get("is_jp", False)),
                        "uid": lic.get("account_id", "-"),
                        "buyer_name": lic.get("buyer_name", "MEMBER"),
                        "expiry": lic.get("expiry", "-")
                    }
        except Exception as _pred_err:
            print(f"[PATCH A2.4] Pred error: {_pred_err}")
        if not pred:
            return jsonify({
                "status": "waiting",
                "msg": "Prediksi belum siap",
                "prediction": None,
                "uid": lic.get("account_id", "-"),
                "buyer_name": lic.get("buyer_name", "MEMBER"),
                "expiry": lic.get("expiry", "-")
            })
        
        # [PATCH E1] Response Cache — biar 1000 member tidak trigger compute berkali-kali
        # Cache di engine (bukan per-request) — TTL 5 detik
        _now_e1 = __import__("time").time()
        _cache = getattr(engine, "_prediction_cache", None)
        if _cache is None:
            engine._prediction_cache = {"data": None, "ts": 0}
            _cache = engine._prediction_cache
        
        _cache_key = f"{pred.get('target')}|{pred.get('bk')}|{pred.get('num')}"
        if _cache["data"] is None or _cache.get("key") != _cache_key or (_now_e1 - _cache["ts"]) > 5:
            # Cache baru — simpan
            _cache["data"] = pred
            _cache["ts"] = _now_e1
            _cache["key"] = _cache_key
        
        # Serve dari cache
        cached_pred = _cache["data"]
        # Pastikan UID & expiry milik member yang minta (per-member)
        response_pred = dict(cached_pred)
        response_pred["uid"] = lic.get("account_id", "-")
        response_pred["buyer_name"] = lic.get("buyer_name", "MEMBER")
        response_pred["expiry"] = lic.get("expiry", "-")
        return jsonify({"status": "ok", "prediction": response_pred, "server_time": _now_e1, "cached": True})
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500


