@app.route('/api/admin/member_stats', methods=['GET'])
def member_stats_v1():
    try:
        if not request.args.get("key") == "MASTER_OWNER_TITAN":
            return jsonify({"status": "error", "msg": "Unauthorized"}), 403
        total = 0
        online = 0
        tokens_with_seen = []
        from datetime import datetime as _dt_ms, timedelta as _td_ms
        now = _dt_ms.now()
        try:
            if hasattr(engine, "licenses"):
                for k, v in engine.licenses.items():
                    total += 1
                    ls = v.get("last_seen")
                    if ls:
                        try:
                            t = _dt_ms.strptime(ls, "%Y-%m-%d %H:%M:%S")
                            if (now - t).total_seconds() < 300:  # 5 menit
                                online += 1
                                tokens_with_seen.append({
                                    "uid": v.get("account_id", "?"),
                                    "last_seen": ls
                                })
                        except: pass
        except: pass
        return jsonify({
            "status": "ok",
            "total_members": total,
            "online_members": online,
            "online_list": tokens_with_seen[:50]
        })
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500

