@app.route('/api/admin/slot_audit', methods=['POST'])
def record_slot_audit():
    data = request.json
    status = data.get("status", "FAIL")
    cause = data.get("cause", "UNKNOWN")
    sol = data.get("solution", "RECALIBRATING")
    entry = slot_engine.record_audit(status, cause, sol)
    
    # Broadcast to Slot Telegram if enabled
    if engine.state["tg_config"].get("slot_enabled"):
        token = engine.state["tg_config"]["slot_token"]
        chat_id = engine.state["tg_config"]["slot_chat_id"]
        if token and chat_id:
            msg = f"\U0001f3b0 <b>TITAN SLOT AUDIT: {status}</b>\n"
            msg += f"\U0001f6a8 CAUSE: <b>{cause}</b>\n"
            msg += f"\U0001f6e1\ufe0f SOLUTION: <i>{sol}</i>\n"
            msg += f"\U0001f3af Resonance: <code>{entry['resonance']}</code>"
            engine.send_tg_msg(msg, custom_token=token, custom_chat_id=chat_id)
            
    return jsonify({"status": "ok"})

@app.route('/api/slot/import_report', methods=['POST'])
def import_slot_report():
    data = request.json
    text = data.get("text", "")
    if not text:
        return jsonify({"status": "error", "message": "No text provided"}), 400
    
    import re
    # Strict regex helpers to extract report keypairs
    def get_val(pattern, txt):
        m = re.search(pattern, txt, re.IGNORECASE)
        return m.group(1).strip() if m else None

    server = get_val(r"SERVER HOST SLOT\s*:\s*(.+)", text)
    game_id = get_val(r"GAME SELECTION\s*/\s*ID\s*:\s*(.+)", text)
    provider = get_val(r"PROVIDER COEFFICIENT\s*:\s*(.+)", text)
    resonance_str = get_val(r"RESONANSI SCATTER\s*:\s*([0-9\.]+)", text)
    latency = get_val(r"LATENCY MESIN PUTAR\s*:\s*(.+)", text)
    accuracy = get_val(r"AKURASI POLA AI\s*:\s*(.+)", text)
    execution = get_val(r"STATUS EKSEKUSI\s*:\s*(.+)", text)
