@app.route('/api/slot/all_ratings')
def slot_all_ratings():
    is_logged_in = False
    page_text = ""
    if engine and engine.driver:
        try:
            with engine.lock:
                current_u = engine.driver.current_url
                if current_u and "login" not in current_u.lower() and "register" not in current_u.lower() and "about:blank" not in current_u.lower():
                    is_logged_in = True
                
                # Fetch DOM text content to do a live scan of the active screen with auto scroll!
                if is_logged_in:
                    try:
                        # Set script timeout to prevent infinite hangs
                        try:
                            engine.driver.set_script_timeout(10)
                        except:
                            pass
                            
                        js_scroll_and_scan = """
                        var callback = arguments[arguments.length - 1];
                        var accumulatedText = document.body.innerText || "";
                        
                        var scrollContainers = [window];
                        try {
                            var allEls = document.querySelectorAll('*');
                            for (var i = 0; i < allEls.length; i++) {
                                var el = allEls[i];
                                var style = window.getComputedStyle(el);
                                if (style && (style.overflowY === 'auto' || style.overflowY === 'scroll') && el.scrollHeight > el.clientHeight) {
                                    scrollContainers.push(el);
                                }
                            }
                        } catch(e) {}

                        var originalPositions = [];
                        for (var i = 0; i < scrollContainers.length; i++) {
                            try {
                                var c = scrollContainers[i];
                                originalPositions.push({
                                    container: c,
                                    top: c === window ? (window.pageYOffset || document.documentElement.scrollTop) : c.scrollTop
                                });
                            } catch(e) {}
                        }

                        var steps = 8;
                        var stepDelay = 200;
                        var stepIdx = 0;

                        function doScrollStep() {
                            if (stepIdx >= steps) {
                                // Restore original positions
                                for (var i = 0; i < originalPositions.length; i++) {
                                    try {
                                        var p = originalPositions[i];
                                        if (p.container === window) {
                                            window.scrollTo(0, p.top);
                                        } else {
                                            p.container.scrollTop = p.top;
                                        }
                                    } catch(e) {}
                                }
                                callback(accumulatedText);
                                return;
                            }

                            // Scroll down
                            for (var i = 0; i < scrollContainers.length; i++) {
                                try {
                                    var c = scrollContainers[i];
                                    if (c === window) {
                                        window.scrollBy(0, 900);
                                    } else {
                                        c.scrollTop += 900;
                                    }
                                } catch(e) {}
                            }

                            setTimeout(function() {
                                try {
                                    accumulatedText += "\\n" + (document.body.innerText || "");
                                } catch(e) {}
                                stepIdx++;
                                doScrollStep();
                            }, stepDelay);
                        }

                        doScrollStep();
                        """
                        page_text = engine.driver.execute_async_script(js_scroll_and_scan)
                    except Exception as scroll_err:
                        print(f"[REALS_CAN] Dynamic progressive scroll failed: {scroll_err}. Falling back to standard snapshot capture.")
                        page_text = engine.driver.execute_script("return document.body.innerText")
        except Exception as e:
            print(f"[REALS_CAN] Scraper error reading DOM inner text: {e}")
            
    ratings = slot_engine.get_all_gacor_ratings(page_text=page_text, is_logged_in=is_logged_in)
    return jsonify(ratings)

