@app.route('/api/save_tg', methods=['POST'])
@require_admin
def save_tg():
    data = request.json or {}
    
    # Update incrementally if keys exist in the payload, preserving existing fields if absent
    if "token" in data:
        engine.state["tg_config"]["token"] = str(data.get("token", "")).strip()
    if "chat_id" in data:
        engine.state["tg_config"]["chat_id"] = str(data.get("chat_id", "")).strip()
    if "enabled" in data:
        engine.state["tg_config"]["enabled"] = bool(data.get("enabled", False))
        
    if "slot_token" in data:
        engine.state["tg_config"]["slot_token"] = str(data.get("slot_token", "")).strip()
    if "slot_chat_id" in data:
        engine.state["tg_config"]["slot_chat_id"] = str(data.get("slot_chat_id", "")).strip()
    if "slot_enabled" in data:
        engine.state["tg_config"]["slot_enabled"] = bool(data.get("slot_enabled", False))
    
    # Editable header/footer template
    if "signal_title" in data:
        engine.state["tg_config"]["signal_title"] = str(data.get("signal_title", ""))
    if "freebet_line" in data:
        engine.state["tg_config"]["freebet_line"] = str(data.get("freebet_line", ""))
    if "channel_line" in data:
        engine.state["tg_config"]["channel_line"] = str(data.get("channel_line", ""))
    if "buttons" in data:
        engine.state["tg_config"]["buttons"] = str(data.get("buttons", ""))
        
    engine._save_config()
    
    token = engine.state["tg_config"].get("token", "")
    chat_id = engine.state["tg_config"].get("chat_id", "")
    enabled = engine.state["tg_config"].get("enabled", False)
    
    s_token = engine.state["tg_config"].get("slot_token", "")
    s_chat_id = engine.state["tg_config"].get("slot_chat_id", "")
    s_enabled = engine.state["tg_config"].get("slot_enabled", False)
    
    msg = ""
    if "token" in data and enabled and token and chat_id:
        tg_m = "\U0001f504 TITANIUM OMEGA: Wingo Sync established!"
        engine.send_tg_msg(tg_m)
        msg += "Wingo Verified. "
    
    if "slot_token" in data and s_enabled and s_token and s_chat_id:
        slot_m = "\U0001f3b0 TITAN SLOT: Black Ops Logic Synced!"
        engine.send_tg_msg(slot_m, custom_token=s_token, custom_chat_id=s_chat_id)
        msg += "Slot Verified."

    return jsonify({"status": "ok", "msg": msg if msg else "Config saved."})

