_screenshot_cache = {"data": None, "ts": 0.0, "interval": 3.0}
@app.route('/api/screenshot')
def browser_ss():
    # [PATCH v35.2] SCREENSHOT CACHE (3 detik TTL — hemat CPU)
    _now = time.time()
    if _screenshot_cache["data"] is not None and (_now - _screenshot_cache["ts"]) < _screenshot_cache["interval"]:
        return Response(_screenshot_cache["data"], mimetype='image/png')
    if not engine.driver:
        # Return a simple dark gray placeholder if engine is not running
        from PIL import Image, ImageDraw
        import io
        img = Image.new('RGB', (450, 600), color=(10, 10, 15))
        draw = ImageDraw.Draw(img)
        draw.text((150, 280), "ENGINE STANDBY", fill=(100, 100, 100))
        draw.text((140, 300), "CLICK INIT ENGINE", fill=(100, 100, 100))
        img_io = io.BytesIO()
        img.save(img_io, 'PNG')
        img_io.seek(0)
        return Response(img_io.getvalue(), mimetype='image/png')
    try:
        with engine.lock:
            engine.ensure_game_tab()
            _ = engine.driver.current_url 
            data = engine.driver.get_screenshot_as_png()
        _screenshot_cache["data"] = data
        _screenshot_cache["ts"] = time.time()
        return Response(data, mimetype='image/png')
    except Exception as e:
        print(f"[SS ERROR] {e}")
        return "Error capturing screen", 500

@app.route('/api/browser_click', methods=['POST'])
def b_click():
    data = request.json
    try:
        x, y = data.get('x', 225), data.get('y', 450)
        from selenium.webdriver.common.action_chains import ActionChains
        with engine.lock:
            body = engine.driver.find_element(By.TAG_NAME, "body")
            # ActionChains.move_to_element_with_offset is relative to the CENTER of the element
            # We must calculate the offset from center to reach absolute (x, y)
            size = body.size
            
            # PROTECTIVE SHIELD FOR PG SOFT 'Rp0,40' ELEMENT (Bet display)
            is_pg, _, _, _ = engine.detect_slot_provider()
            
            if is_pg and size['width'] > 0 and size['height'] > 0:
                xr = x / size['width']
                yr = y / size['height']
                # The Rp0,40 coin indicator is in the middle column (0.33 to 0.67) and the status row (0.87 to 0.93)
                if 0.33 <= xr <= 0.67 and 0.86 <= yr <= 0.93:
                    msg_shield = "🛡️ [BENTENG SALDO] Klik pada area bet (Rp0,40) DIBLOKIR demi keamanan agar taruhan tidak melonjak ke 1 JUTA!"
                    engine._add_log(msg_shield)
                    print(msg_shield)
                    return jsonify({"status": "blocked", "msg": msg_shield})
            
            mid_x = size['width'] / 2
            mid_y = size['height'] / 2
            
            actions = ActionChains(engine.driver)
            actions.move_to_element_with_offset(body, x - mid_x, y - mid_y).click().perform()
        return jsonify({"status": "ok"})
    except Exception as e:
        print(f"Click Error: {e}")
        return jsonify({"status": "err", "msg": str(e)}), 400

