@app.route('/api/toggle_auto_scroll', methods=['POST'])
def toggle_auto_scroll():
    data = request.json or {}
    if "enabled" in data:
        engine.auto_scroll_enabled = bool(data["enabled"])
    else:
        engine.auto_scroll_enabled = not getattr(engine, "auto_scroll_enabled", True)
        
    if "interval" in data:
        try:
            engine.auto_scroll_interval = max(10, int(data["interval"]))
        except: pass
        
    if "auto_scroll" in engine.state:
        engine.state["auto_scroll"]["enabled"] = engine.auto_scroll_enabled
        engine.state["auto_scroll"]["interval"] = getattr(engine, "auto_scroll_interval", 90)
        
    status_str = "AKTIF (" + str(getattr(engine, "auto_scroll_interval", 90)) + "s)" if engine.auto_scroll_enabled else "NON-AKTIF"
    engine._add_log(f"⚙️ [CONFIG] Mode Auto-Scroll Anti-Stuck diubah: {status_str}")
    return jsonify({
        "status": "ok",
        "enabled": engine.auto_scroll_enabled,
        "interval": getattr(engine, "auto_scroll_interval", 90),
        "count": getattr(engine, "auto_scroll_count", 0)
    })

@app.route('/api/goto_login', methods=['POST'])
def goto_login_route():
    if not engine.driver:
        return jsonify({"status": "err", "msg": "Engine not running"}), 400
    try:
        with engine.lock:
            from urllib.parse import urlparse
            base_url = LOGIN_URL
            if engine.target_url and engine.target_url.startswith("http"):
                parsed = urlparse(engine.target_url)
                base_url = f"{parsed.scheme}://{parsed.netloc}/#/login"
            engine.driver.get(base_url)
        return jsonify({"status": "ok", "msg": "Navigating to Login Page..."})
    except Exception as e:
        return jsonify({"status": "err", "msg": str(e)}), 500

@app.route('/api/start_engine', methods=['POST'])
def start_engine():
    data = request.json or {}
    if data.get("reset"):
        engine.processed_p.clear()
        engine.state["history"] = []
        engine.state["prediction"] = None
        engine.state["stats"] = {"win": 0, "lose": 0, "acc": 0, "win_jp": 0, "current_lose_streak": 0, "max_lose_streak": 0}
        engine.state["m_level"] = 1
        # Deep Brain Reset
        engine.brain.history_nums = []
        engine.brain.history_bks = []
        engine.brain.history_colors = []
        engine.brain.processed_p = set()
        engine.brain.sequence_map.clear()
        engine.brain.update_stats()
        engine.state["chart_stats"] = engine.brain.chart_stats.copy()
        engine._add_log("SYSTEM RESET: Neural Memory Purged. Ready for Fresh Matrix Sync.")
    
    if engine._loop_active:
        return jsonify({"status": "running", "msg": "Engine Startup already in progress or active"})
    
    # [WORKFLOW v2] Reset prediction & active_p supaya startup bersih dari sisa sesi lama
    engine.state["prediction"] = None
    engine.state["active_p"] = None
    engine.state["active_period"] = None
    engine.state["currentPeriod"] = None
    engine.state["target_period"] = None
    engine.state["mode_raw"] = "60"
    engine.state["current_mode"] = "WAITING FOR LOGIN"
    engine.processed_p = set()
    engine.last_observed_timer = ""
    engine.last_timer_change_time = time.time()
    
    # [v44 FIX] Force reset active_sig agar tidak ada filter stale dari sesi lama
    try:
        from datetime import datetime as _dt_v44
        engine.state["active_sig"] = _dt_v44.now().strftime("%Y%m%d") + "10001"
        engine.state["history"] = []
        engine.state["active_p"] = None
        engine.state["prediction"] = None
        print(f"[v44] Forced active_sig → {engine.state['active_sig']} (mode 1m)")
    except: pass
    engine._add_log("🔄 [WORKFLOW] State di-reset. Alur: Login via Helper → Pilih Mode (30s/1m/3m/5m).")
    
    engine.is_running = True
    threading.Thread(target=engine.start_browser, daemon=True).start()
    threading.Thread(target=engine.monitor_loop, daemon=True).start()
    return jsonify({"status": "success", "msg": "Engine Startup Initiated"})

