@app.route('/api/device/register', methods=['POST'])
def api_device_register():
    """Terima fingerprint device dari member, simpan sebagai log"""
    try:
        data = request.json or {}
        device_fp = str(data.get("fp", "")).strip()[:64]
        key = str(data.get("key", "")).strip()[:200]
        
        if not device_fp or not key:
            return jsonify({"status": "error", "msg": "missing data"}), 400
        
        # Simpan di license DB
        import json as _json_dev
        lic_file = "/home/container/central_licenses.json"
        if not os.path.exists(lic_file):
            return jsonify({"status": "error", "msg": "no license db"}), 404
        
        with open(lic_file, "r") as f:
            lics = _json_dev.load(f)
        
        if key not in lics:
            return jsonify({"status": "error", "msg": "license not found"}), 404
        
        # Init device list kalau belum ada
        if "devices" not in lics[key]:
            lics[key]["devices"] = []
        
        # Rekam device (unique)
        if device_fp not in lics[key]["devices"]:
            lics[key]["devices"].append(device_fp)
            # Keep max 10 device
            lics[key]["devices"] = lics[key]["devices"][-10:]
        
        lics[key]["last_device_activity"] = datetime.now().isoformat()
        lics[key]["last_device_fp"] = device_fp
        
        with open(lic_file, "w") as f:
            _json_dev.dump(lics, f, indent=2)
        
        # Alert kalau > 2 devices
        device_count = len(lics[key]["devices"])
        alert = device_count > 2
        
        return jsonify({"status": "ok", "device_count": device_count, "alert": alert})
    except Exception as e:
        return jsonify({"status": "error", "msg": str(e)}), 500

